def transform(grid):
    from collections import defaultdict
    g = np.array(grid); H, W = g.shape
    R = np.zeros((H, W), int); D = np.zeros((H, W), int)
    for y in range(H):
        for x in range(W - 1, -1, -1):
            R[y, x] = 1 + (R[y, x + 1] if x + 1 < W and g[y, x + 1] == g[y, x] else 0)
    for x in range(W):
        for y in range(H - 1, -1, -1):
            D[y, x] = 1 + (D[y + 1, x] if y + 1 < H and g[y + 1, x] == g[y, x] else 0)

    def bordered(y0, x0, y1, x1):
        c = g[y0, x0]; w = x1 - x0 + 1; h = y1 - y0 + 1
        return (R[y0, x0] >= w and D[y0, x0] >= h and g[y1, x0] == c and R[y1, x0] >= w
                and g[y0, x1] == c and D[y0, x1] >= h)

    # 1. find the four frames (same size, uniform border)
    groups = defaultdict(list)
    for y0 in range(H):
        for x0 in range(W):
            for h in range(4, 16):
                for w in range(4, 16):
                    y1, x1 = y0 + h - 1, x0 + w - 1
                    if y1 < H and x1 < W and bordered(y0, x0, y1, x1):
                        groups[(h, w)].append((y0, x0, y1, x1))
    key = max([k for k, v in groups.items() if len(v) == 4], key=lambda k: k[0] * k[1])
    frames = groups[key]
    inter = [g[a + 1:c, b + 1:d].copy() for (a, b, c, d) in frames]
    fcol = [int(g[a, b]) for (a, b, c, d) in frames]
    ei = [i for i in range(4) if not inter[i].any()][0]

    # 2. partner of the empty frame = other frame in its smallest enclosing rectangle
    fy0, fx0, fy1, fx1 = frames[ei]
    best = None
    for y0 in range(fy0):
        for y1 in range(fy1 + 1, H):
            for x0 in range(fx0):
                for x1 in range(fx1 + 1, W):
                    area = (y1 - y0) * (x1 - x0)
                    if best is not None and area >= best[0]:
                        continue
                    if not bordered(y0, x0, y1, x1):
                        continue
                    inside = [i for i, (a, b, c, d) in enumerate(frames)
                              if a > y0 and b > x0 and c < y1 and d < x1]
                    if len(inside) == 2 and ei in inside:
                        best = (area, [i for i in inside if i != ei][0])
    if best is not None:
        qi = best[1]
    else:
        cy, cx = (fy0 + fy1) / 2, (fx0 + fx1) / 2
        qi = min([i for i in range(4) if i != ei],
                 key=lambda i: (frames[i][0] - fy0) ** 2 + (frames[i][1] - fx0) ** 2)
    ex = [i for i in range(4) if i not in (ei, qi)]
    Q = inter[qi]
    emit(Q.copy(), "Copy the question frame's interior (partner of the empty frame).")

    # 3. candidate transforms
    def parity(X, fc):
        cols = {}
        for (y, x) in zip(*np.nonzero(X)):
            cols.setdefault((y + x) % 2, int(X[y, x]))
        if not cols:
            return None
        for p in (0, 1):
            cols.setdefault(p, cols[1 - p])
        out = np.zeros_like(X)
        for y in range(X.shape[0]):
            for x in range(X.shape[1]):
                if X[y, x] == 0:
                    out[y, x] = cols[(y + x) % 2]
        return out

    def mirror(X, fc):
        nz = np.argwhere(X != 0)
        if len(nz) == 0:
            return None
        h, w = X.shape
        out = X.copy()
        for F in (X[:, ::-1], X[::-1, :], X[::-1, ::-1]):
            out = np.where(out == 0, F, out)
        y0, x0 = nz.min(0); y1, x1 = nz.max(0)
        cov = np.zeros(X.shape, bool)
        for (a, b, c, d) in [(y0, x0, y1, x1), (y0, w - 1 - x1, y1, w - 1 - x0),
                             (h - 1 - y1, x0, h - 1 - y0, x1),
                             (h - 1 - y1, w - 1 - x1, h - 1 - y0, w - 1 - x0)]:
            cov[a:c + 1, b:d + 1] = True
        out[(~cov) & (out == 0)] = fc
        return out

    def lines(X, c):
        out = X.copy()
        for y in range(X.shape[0]):
            xs = list(np.nonzero(X[y])[0])
            for a, b in zip(xs, xs[1:]):
                out[y, a + 1:b] = c
        for x in range(X.shape[1]):
            ys = list(np.nonzero(X[:, x])[0])
            for a, b in zip(ys, ys[1:]):
                out[a + 1:b, x] = c
        return out

    result = None
    pairs = [(ex[0], ex[1]), (ex[1], ex[0])]
    for f in (parity, mirror):
        for s, t in pairs:
            r = f(inter[s], fcol[s])
            if r is not None and np.array_equal(r, inter[t]):
                result = f(Q, fcol[qi]); break
        if result is not None:
            break
    if result is None:
        for s, t in pairs:
            S = inter[s]
            for c in set(np.unique(inter[t]).tolist()) - {0}:
                if np.array_equal(lines(S, c), inter[t]):
                    diff = set(np.unique(Q).tolist()) - {0} - set(np.unique(S).tolist())
                    cq = diff.pop() if len(diff) == 1 else c
                    result = lines(Q, cq); break
            if result is not None:
                break
    if result is None:
        result = Q.copy()
    emit(result.copy(), "Apply the example pair's relation to the question to fill the empty frame.")
    return result
